import ast,re
from pathlib import Path
p=Path('/workspace/wandb/offline-run-20260821_033838-wi4fh8cz/files/output.log')
wanted={0,1,9,10,19,20,29,30,39,40,49,50,59,60,69,70,79,80,89,90,99,100,149,150,189,190,199}
for line in p.open(errors='replace'):
