        ks=['eval/nq_test','eval/nq_test/response_len/mean','eval/nq_test/truncated_ratio']
    else:
        ks=[k for k in d if any(x in k for x in ['loss','grad','entropy','kl','lr'])]
    print(kind,step,{k:d.get(k) for k in ks})
